completed_tool_actions.command:
/bin/bash -lc "python -B - <<'PY'
import json
from pathlib import Path
for log in sorted(Path('.').glob('*/actions.json')):
    print(log)
    for op in json.loads(log.read_text())['operations']:
        command = op.get('command')
        if command is None:
            print(op)
        else:
            print('exit', op.get('exit'), command.replace('\\\\n','\\\\n').split('\\\\n',1)[0][:750])
PY"
